const prng = s => () => { s = (s * 1664525 + 1013904223) % 4294967296; return s / 4294967296; };
function miniSkyline(seed, w, y0, h) {
  const r = prng(seed * 977 + 13);
  let x = -4, out = '';
  while (x < w) {
    const bw = 20 + r() * 40, bh = h * (0.25 + r() * 0.65);
    out += `<rect x="${x.toFixed(1)}" y="${(y0 - bh).toFixed(1)}" width="${bw.toFixed(1)}" height="${(bh + 2).toFixed(1)}" fill="#1B1D22"/>`;
    for (let wy = y0 - bh + 10; wy < y0 - 8; wy += 13)
      for (let wx = x + 5; wx < x + bw - 6; wx += 10)
        if (r() < 0.13) out += `<rect x="${wx.toFixed(1)}" y="${wy.toFixed(1)}" width="3.5" height="5.5" fill="#FFB000" opacity=".85"/>`;
    x += bw + 1;
  }
  return out;
}
