/* ================================================================ Rails, tilt, cursor, magnets */
function railUpdate(rail) {
  if (!rail) return;
  const bar = $('#' + rail.id + 'Bar');
  if (!bar) return;
  const max = rail.scrollWidth - rail.clientWidth;
  const vis = rail.scrollWidth ? Math.min(1, rail.clientWidth / rail.scrollWidth) : 1;
  bar.style.width = (vis * 100) + '%';
  bar.style.transform = `translateX(${max > 0 ? (rail.scrollLeft / max) * (1 / vis - 1) * 100 : 0}%)`;
}
function railParallax(rail) {
  if (!rail || REDUCE) return;
  const rr = rail.getBoundingClientRect(), mid = rr.left + rr.width / 2;
  $$('.frame', rail).forEach(f => {
    const r = f.getBoundingClientRect();
    f.style.setProperty('--px', ((r.left + r.width / 2 - mid) * -0.07).toFixed(1) + 'px');
  });
}
function initRail(rail) {
  if (!rail) return;
  let down = false, sx = 0, sl = 0, moved = false;
  rail.addEventListener('pointerdown', e => {
    if (e.pointerType !== 'mouse' || e.button !== 0 || e.target.closest('input,label,select,a,textarea,.btn,.chip')) return;
    down = true; moved = false; sx = e.clientX; sl = rail.scrollLeft;
  });
  window.addEventListener('pointermove', e => {
    if (!down) return;
    const dx = e.clientX - sx;
    if (Math.abs(dx) > 5) { moved = true; rail.classList.add('drag'); }
    if (moved) rail.scrollLeft = sl - dx;
  });
  window.addEventListener('pointerup', () => {
    if (!down) return;
    down = false;
    rail.classList.remove('drag');
    if (moved) { rail._dragged = true; setTimeout(() => { rail._dragged = false; }, 60); }
  });
  rail.addEventListener('click', e => { if (rail._dragged) { e.stopPropagation(); e.preventDefault(); } }, true);
  rail.addEventListener('scroll', () => { railUpdate(rail); if (rail.id === 'runRail') railParallax(rail); }, { passive: true });
  window.addEventListener('resize', () => railUpdate(rail));
}

