    c.fillStyle = L.color;
    const wins = [];
    let x = -20;
    while (x < cw) {
      const w = L.minW + rand() * (L.maxW - L.minW), h = H * (L.minH + rand() * (L.maxH - L.minH)), y = H - h;
      c.fillRect(x, y, w, h + 2);
      if (rand() < 0.35) { const sw = w * 0.6; c.fillRect(x + (w - sw) / 2, y - h * 0.08, sw, h * 0.08 + 1); }
      if (rand() < 0.2) c.fillRect(x + w / 2 - 1.5, y - h * 0.16, 3, h * 0.16 + 1);
      if (L.win) for (let wy = y + 12; wy < H - 10; wy += 14) for (let wx = x + 8; wx < x + w - 8; wx += 10) if (rand() < L.win) wins.push([wx, wy]);
      x += w + (rand() < 0.3 ? rand() * 10 : 0);
    }
    if (L.landmarks) {
      c.fillStyle = '#2A2D35';
      const ex = cw * 0.62, eh = H * 0.56;
      c.fillRect(ex - 46, H - eh * 0.55, 92, eh * 0.55 + 2); c.fillRect(ex - 34, H - eh * 0.78, 68, eh * 0.23 + 1);
      c.fillRect(ex - 22, H - eh * 0.92, 44, eh * 0.14 + 1); c.fillRect(ex - 12, H - eh * 1.02, 24, eh * 0.10 + 1);
      c.fillRect(ex - 3.5, H - eh * 1.12, 7, eh * 0.10 + 1); c.fillRect(ex - 1, H - eh * 1.36, 2, eh * 0.24 + 1);
      const cx = cw * 0.27, ch = H * 0.5;
      c.fillRect(cx - 32, H - ch, 64, ch + 2);
      for (let k = 0; k < 5; k++) { const r = 30 - k * 5.5, cy = H - ch - k * 13; c.beginPath(); c.arc(cx, cy, r, Math.PI, 0); c.lineTo(cx + r, cy + 13); c.lineTo(cx - r, cy + 13); c.fill(); }
      c.fillRect(cx - 1, H - ch - 5 * 13 - 30, 2, 32);
      for (let wy = H - eh * 0.5; wy < H - 10; wy += 14) for (let wx = ex - 38; wx < ex + 38; wx += 10) if (rand() < 0.16) wins.push([wx, wy]);
      for (let wy = H - ch + 12; wy < H - 10; wy += 14) for (let wx = cx - 26; wx < cx + 26; wx += 10) if (rand() < 0.16) wins.push([wx, wy]);
    }
    const isLit = new Uint8Array(wins.length), litArr = [];
    wins.forEach((_, i) => { if (rand() < 0.3) { isLit[i] = 1; litArr.push(i); } });
